import { infoManager } from '@/api/managers/infoManager';
import { Info } from '@/types/TInfo';
import { defineStore } from 'pinia'

export const useInfoStore = defineStore('info', {

  state: () => ({
    info: new Info()
  }),

  actions: {

    async fetchInfo(locale: string) {
      const i = await infoManager.infodata(locale);
      this.setInfo(i);
    },

    setInfo(i: Info) {
      this.info = i;
    }

  }

})