import { Group, IGroupDict } from '@/types/TGroup';
import { MacroGroup, IGroupInMacrogroupDict, IMacroGroupDict } from '@/types/TMacroGroup';
import { IProgectInGroupDict, Project } from '@/types/TProject';
import { IGroup } from '@/types/IGroup';
import { SuperGroup } from '@/types/TSuperGroup';
import { groupManager } from '@/api/managers/groupManager';

import { defineStore } from 'pinia'

interface IGroupState {
  MacroGroups: IMacroGroupDict;
  GroupsWithNoMacroGroup: IGroupDict;
  Groups: IGroupDict;
  GroupsInMacroGroups: IGroupInMacrogroupDict;
  ProjectsInGroups: IProgectInGroupDict;
  Projects: Project[];
  ActiveGroup: SuperGroup | null;
  Search: string;
}

export const useGroupStore = defineStore('group', {

  state: (): IGroupState => ({
    MacroGroups: {},
    GroupsWithNoMacroGroup: {},
    Groups: {},
    GroupsInMacroGroups: {},
    ProjectsInGroups: {},
    Projects: [],
    ActiveGroup: null,
    Search: '',
  }),

  getters: {
    macroGroups:            (state): IMacroGroupDict           => state.MacroGroups,
    macroGroup:             (state): (id: number) => MacroGroup => (id: number) => state.MacroGroups[id],
    search:                 (state): string                    => state.Search,
    activeGroup:            (state): SuperGroup | null         => state.ActiveGroup,
    groupsWithNoMacroGroup: (state): IGroupDict                => state.GroupsWithNoMacroGroup,
    groupsInMacroGroup:     (state): (id: number) => Group[]   => (id: number) => state.GroupsInMacroGroups[id],
    groups:                 (state): IGroupDict                => state.Groups,
    projectsInGroup:        (state): (id: number) => Project[] => (id: number) => state.ProjectsInGroups[id],
    projects:               (state): Project[]                 => state.Projects,
    superGroups:            (state): SuperGroup[]              => [
      ...Object.values(state.MacroGroups),
      ...Object.values(state.GroupsWithNoMacroGroup),
    ],
    filteredProjects:       (state): Project[]                 => {
      const s = state.Search.toLowerCase();
      return state.Projects.filter(
        (p) => p.title.toLowerCase().includes(s) || p.description.toLowerCase().includes(s),
      );
    },

  },

  actions: {

    reset() {
      this.MacroGroups            = {};
      this.GroupsWithNoMacroGroup = {};
      this.Groups                 = {};
      this.GroupsInMacroGroups    = {};
      this.ProjectsInGroups       = {};
    },

    search(s: string) {
      this.Search = s;
    },

    setActiveGroup(sg: SuperGroup | null) {
      this.ActiveGroup = sg;
    },
  
    fetchProjects(locale) {
      return groupManager
        .projects(locale)
        .then((i) => { this.setProjects(i.map((p) => new Project(p))); })
        .catch()
    },
  
    fetchMacroGroups(locale) {
      return groupManager
        .macrogroups(locale)
        .then((i) => { i.forEach((m) => { this.setMacroGroups(new MacroGroup(m)); }); })
        .catch()
    },
  
    fetchGroupsWithNoMacroGroup(locale) {
      return groupManager
        .groupsNoMacrogroups(locale)
        .then((i) => {
          i.forEach((g: IGroup) => {
            const gr = new Group(g);
            this.setGroupWithNoMacroGroup(gr);
            this.setGroup(gr);
          });
        })
    },
  
    fetchGroups(locale) {
      return groupManager
        .groups(locale)
        .then((i) => { i.forEach((g) => { this.setGroup(new Group(g)); }); })
    },
  
    fetchGroupsByMacroGroupId(locale, id) {
      return groupManager
        .groupsInMacrogroup(locale, id)
        .then((i) => {
          this.setGroupsOfMacrogroup({
            id,
            gps: i.map((g) => {
              const gr = new Group(g);
              this.setGroup(gr);
              return gr;
            }),
          })
        })
    },
  
    fetchProjectsByGroupId(locale, id) {
      return groupManager
        .projectsInGroup(locale, id)
        .then((i) => {
          this.setProjectsOfGroup({
            id,
            prj: i.map((p) => new Project(p)),
          });
        })
    },

    setMacroGroups(mc) {
      this.MacroGroups[mc.id] = mc;
    },

    setGroupWithNoMacroGroup(g) {
      this.GroupsWithNoMacroGroup[g.id] = g;
    },
  
    setGroup(g) {
      this.Groups[g.id] = g;
    },
  
    setGroupsOfMacrogroup(g) {
      this.GroupsInMacroGroups[g.id] = g.gps;
    },
  
    setProjectsOfGroup(g) {
      this.ProjectsInGroups[g.id] = g.prj;
    },
  
    setProjects(ps) {
      this.Projects = ps;
    },

  }

})
