import { picturesManager } from '@/api/managers/picturesManager';
import { IPictures } from '@/types/IPictures';
import { defineStore } from 'pinia'

interface ISettings {
  portalSections: string[];
  showAdminButton: boolean;
  pictures: IPictures[];
}

export const useSettingsStore = defineStore('settings', {

  state: (): ISettings => ({
    portalSections: [],
    showAdminButton: false,
    pictures: [],
  }),

  actions: {

    async fetchPictures(locale: string) {
      const ps = await picturesManager.pictures(locale);
      const pictures = ps.sort((a: IPictures, b: IPictures) => {
        if (a.order < b.order) { return -1; }
        if (a.order > b.order) { return 1; }
        return 0;
      });
      this.pictures = pictures;
    },

  }

});