import store from '@/store/root';
import { useInfoStore } from '@/store/info';
import { useSettingsStore } from '@/store/settings';
import { useGroupStore } from '@/store/group';
import { useRootStore } from '@/store/root';

/**
 * Fetch some general application data
 */
export default async function fetchData(locale: string) {
  useRootStore().showLoader();
  await Promise.allSettled([
    useInfoStore().fetchInfo(locale),
    useSettingsStore().fetchPictures(locale),
    useGroupStore().fetchMacroGroups(locale),
    useGroupStore().fetchGroupsWithNoMacroGroup(locale),
    useGroupStore().fetchProjects( locale),
  ]);
  useRootStore().hideLoader();
}
